#!/usr/bin/env python3
"""Rebuild issue #471's exact sourced follow-up roster."""
import json
from pathlib import Path
OWN=Path(__file__).resolve().parent
assessment=json.loads((OWN/'assessment.json').read_text(encoding='utf-8'))
lookup={x['id']:x for x in assessment['subjects']}
ghana=sorted(x['id'] for x in assessment['subjects'] if x['area_id']=='framework:area:ghana:10a3784bfa3f' and x['status']=='insufficient-evidence')
civ=sorted(x['id'] for x in assessment['subjects'] if x['area_id']=='framework:area:ivory-coast:86d2b1a53604')
gambia=sorted(x['id'] for x in assessment['subjects'] if x['area_id']=='framework:area:gambia-the:4d8ac268bae1' and x['status']=='insufficient-evidence')
city=['atlas:city:GMB-2153']
assert len(ghana)==84 and len(civ)==63 and len(gambia)==10 and len(city)==1
handoffs=[
 {'id':'banjul-cross-lga-parent','issue':830,'url':'https://github.com/ChengshuLi/WorldAtlas/issues/830','title':'Resolve Banjul city aggregation role and cross-LGA parent','status':'blocked','depends_on':[471],'subject_ids':city,'related_source_member_ids':lookup[city[0]]['source_member_ids'],'finding':'Atlas metadata describes one coextensive Banjul province parent, while the nine declared 2020 district members reconstruct the city footprint and cross Brikama, Kanifing, and Banjul LGAs. The correct statutory/urban role remains unknown.','engineering_handoff':'No geometry change is proposed. After primary legal/source review, hand a supported role/parent metadata correction to engineering while preserving ID and footprint; if unresolved, retain the source gap.'},
 {'id':'gambia-district-current-boundaries','issue':835,'url':'https://github.com/ChengshuLi/WorldAtlas/issues/835','title':'Reconcile ten Gambia district footprints against current official sources','status':'blocked','depends_on':[471],'subject_ids':gambia,'finding':'These ten standalone Gambia district rows have exact pinned 2020 source IDs/names/parents, but Atlas-to-2020-source equal-area IoU is below 0.95. No current authoritative district boundary geometry was located.','engineering_handoff':'No boundary edit is justified by overlap alone. Obtain current official boundary geometry or a sourced crosswalk and only then hand exact demonstrated changes to engineering.'},
 {'id':'ghana-gss-2021-crosswalk','issue':831,'url':'https://github.com/ChengshuLi/WorldAtlas/issues/831','title':'Crosswalk Ghana’s 84 unresolved district rows to 2021 GSS geography','status':'blocked','depends_on':[471,810],'subject_ids':ghana,'related_disjoint_issue':810,'finding':'84 exact Ghana subjects remain below the documented source-to-GSS, atlas-to-source, or named-parent comparison threshold. Row-level differences cannot distinguish boundary change, statistical redistricting, or source quality.','engineering_handoff':'No footprint change is supported by current evidence. If row-level official codes and geometry establish corrections, record exact source IDs, neighboring effects, preservation requirements, and integration acceptance for engineering.'},
 {'id':'civ-official-role-crosswalk','issue':832,'url':'https://github.com/ChengshuLi/WorldAtlas/issues/832','title':'Reconcile Côte d’Ivoire’s 63 scoped units to official role and codes','status':'blocked','depends_on':[471],'subject_ids':civ,'finding':'The retained 2021 source calls its 510 ADM3 features Departments, while official DGAT and ANStat 2021 counts and roles differ. The 63 IDs map to source geometry and 2016 parents, but no official exact-row role/code crosswalk was established.','engineering_handoff':'No location or parent edit is yet supported. After official decree/code reconciliation, identify specific role/parent changes and affected neighbors for engineering; do not convert counts alone into a semantic-tier correction.'}
]
result={'issue':471,'issue_url':'https://github.com/ChengshuLi/WorldAtlas/issues/471','created_at_utc':'2026-10-05','handoffs':handoffs,'subject_count':sum(len(h['subject_ids']) for h in handoffs),'notes':['The Ghana child roster is disjoint from #810’s 31 exact subject IDs; it depends on #810 so common source restoration findings can be reused.','All four child issues remain status:blocked pending the declared dependencies.','No source follow-up authorizes live geography edits, historical imports, publication, or regional approval.']}
(OWN/'findings-and-handoffs.json').write_text(json.dumps(result,ensure_ascii=False,sort_keys=True,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'followups':[(h['issue'],len(h['subject_ids'])) for h in handoffs],'subjects':result['subject_count']},indent=2))
